// Package filestore keeps uploaded files (verification pictures, profile
// photos, classroom materials and submissions) either on local disk or in the
// database. Disk is the default for a single long-running server; the database
// suits hosts without a persistent filesystem, such as serverless platforms.
package filestore

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/jmoiron/sqlx"
)

var ErrNotFound = errors.New("file not found")

// Store saves, loads and deletes file contents by an opaque key. Keys are
// generated by the server (UUIDs), never taken from the client.
type Store interface {
	Put(ctx context.Context, key, mime string, content []byte) error
	Get(ctx context.Context, key string) ([]byte, error)
	Delete(ctx context.Context, key string)
}

// New returns the store selected by kind: "disk" (files under dir) or
// "database" (the stored_files table).
func New(kind string, db *sqlx.DB, dir string) (Store, error) {
	switch kind {
	case "", "disk":
		return Disk{Dir: dir}, nil
	case "database":
		return Database{DB: db}, nil
	default:
		return nil, fmt.Errorf("unknown FILE_STORAGE %q (use disk or database)", kind)
	}
}

// Disk stores each file as dir/<key> with owner-only permissions.
type Disk struct{ Dir string }

func (d Disk) path(key string) string { return filepath.Join(d.Dir, filepath.Base(key)) }

func (d Disk) Put(_ context.Context, key, _ string, content []byte) error {
	if err := os.MkdirAll(d.Dir, 0o700); err != nil {
		return err
	}
	return os.WriteFile(d.path(key), content, 0o600)
}

func (d Disk) Get(_ context.Context, key string) ([]byte, error) {
	content, err := os.ReadFile(d.path(key))
	if errors.Is(err, os.ErrNotExist) {
		return nil, ErrNotFound
	}
	return content, err
}

func (d Disk) Delete(_ context.Context, key string) {
	if key != "" {
		_ = os.Remove(d.path(key))
	}
}

// Database stores files in the stored_files table (migration 005).
type Database struct{ DB *sqlx.DB }

func (s Database) Put(ctx context.Context, key, mime string, content []byte) error {
	_, err := s.DB.ExecContext(ctx, `INSERT INTO stored_files (storage_key, mime_type, byte_size, content) VALUES (?, ?, ?, ?)`, key, mime, len(content), content)
	return err
}

func (s Database) Get(ctx context.Context, key string) ([]byte, error) {
	var content []byte
	err := s.DB.GetContext(ctx, &content, `SELECT content FROM stored_files WHERE storage_key = ?`, key)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	return content, err
}

func (s Database) Delete(ctx context.Context, key string) {
	if key != "" {
		_, _ = s.DB.ExecContext(ctx, `DELETE FROM stored_files WHERE storage_key = ?`, key)
	}
}
